#include "../../src/hardware/NeuralChipHAL.h"
#include <cassert>
int main(){ dnxr::SimulatedNeuralChipHAL hal(16); hal.connect("seven_modality"); dnxr::SafeNeuralStimulusCommandFixed c; c.sequenceId=1; c.monotonicTimestampMs=1; c.boundedChannels.push_back(0.1f); c.modalityIntensities.fill(0.1f); c.aggregateSensoryLoad=0.1f; c.intensityScale=0.1f; c.riskScore=0.1f; c.safetyMode="unit"; c.calibrationProfileId="cal"; c.fiveSenseCoverage=true; c.coveragePolicy=dnxr::StimulusCoveragePolicy::FullMultisensoryFrame; c.requiredModalityCount=static_cast<std::size_t>(dnxr::SensoryModality::Count); c.requiredModalities={dnxr::SensoryModality::Visual,dnxr::SensoryModality::Auditory,dnxr::SensoryModality::HapticTouch,dnxr::SensoryModality::Olfactory,dnxr::SensoryModality::Gustatory,dnxr::SensoryModality::Proprioceptive,dnxr::SensoryModality::Vestibular}; c.allowStimulusDispatch=true; assert(hal.writeSafeStimulus(c)); assert(hal.lastAcceptedStimulus().modalityIntensities.size()==static_cast<std::size_t>(dnxr::SensoryModality::Count)); return 0; }
